import pytest
from task_api import TaskManagerService

def test_create_and_fetch_task():
    svc = TaskManagerService()
    t = svc.create_task("t1", "Audit AST", "Zero hallucinations")
    assert t.title == "Audit AST"
    assert svc.get_task("t1") is not None
